from __future__ import annotations

from playwright.sync_api import Page, expect


class ContactFormPage:
    def __init__(self, page: Page) -> None:
        self.page = page
        self.name_input = page.get_by_label("Name")
        self.email_input = page.get_by_label("Email")
        self.message_input = page.get_by_label("Message")
        self.submit_button = page.get_by_role("button", name="Send message")
        self.email_error = page.get_by_test_id("contact-email-error")
        self.success_banner = page.get_by_test_id("contact-success")

    def open(self, base_url: str) -> None:
        # The test waits on visible elements instead of fixed sleeps.
        self.page.goto(f"{base_url.rstrip('/')}/contact", wait_until="domcontentloaded")
        expect(self.submit_button).to_be_visible()

    def submit_with_invalid_email(self) -> None:
        self.name_input.fill("Test User")
        self.email_input.fill("not-an-email")
        self.message_input.fill("This is a deterministic validation test message.")
        self.submit_button.click()

    def submit_valid_message(self, email: str) -> None:
        self.name_input.fill("Test User")
        self.email_input.fill(email)
        self.message_input.fill("This message is generated by an automated test.")
        self.submit_button.click()
